import assert from 'node:assert/strict';
import { createController } from './src/controller.js';

const deferred = () => {
  let resolve, reject;
  const promise = new Promise((res, rej) => { resolve = res; reject = rej; });
  return { promise, resolve, reject };
};
const pending = [];
const records = [];
const renders = [];
const controller = createController({
  service: { commit(snapshot) { const request = deferred(); pending.push({ snapshot, ...request }); return request.promise; } },
  audit: { record(entry) { records.push(entry); } },
  render(view) { renders.push(view); },
});

controller.open('one', 'ava');
controller.edit('first');
const first = controller.submit();
assert.equal(typeof first.then, 'function');
assert.deepEqual(records, []);
assert.deepEqual(renders, []);
pending[0].resolve({ revision: 1 });
assert.deepEqual(await first, { revision: 1 });
assert.deepEqual(records, [{ doc: 'one', actor: 'ava', text: 'first', revision: 1 }]);
assert.deepEqual(renders, [{ status: 'saved', doc: 'one' }]);

controller.edit('bad');
const rejected = controller.submit();
pending[1].reject(new Error('nope'));
assert.equal(await rejected, undefined);
assert.equal(records.length, 1);
assert.deepEqual(renders.at(-1), { status: 'error', doc: 'one' });

controller.edit('older');
const older = controller.submit();
controller.edit('newer');
const newer = controller.submit();
pending[3].resolve({ revision: 3 });
await newer;
pending[2].resolve({ revision: 2 });
await older;
assert.equal(records.length, 3);
assert.deepEqual(renders.at(-1), { status: 'saved', doc: 'one' });

controller.edit('closed');
const closed = controller.submit();
controller.close();
pending[4].resolve({ revision: 4 });
await closed;
assert.equal(records.length, 4);
assert.deepEqual(renders.at(-1), { status: 'saved', doc: 'one' });

console.log('controller async submit checks passed');
